const raw = $json.body ?? $json;

try {
  if (!raw.workflow) throw new Error("Missing 'workflow' field in request body");

  const wf = raw.workflow;
  const nodes = wf.nodes;
  const connections = wf.connections;

  if (!Array.isArray(nodes) || nodes.length === 0)
    throw new Error("No nodes found in workflow");

  if (!connections || typeof connections !== "object")
    throw new Error("No connections object found in workflow");

  // ---- Build helper lookups ----
  const nodeNames = nodes.map(n => n.name);
  const sourceNames = Object.keys(connections);

  // Nodes that appear as a target anywhere in connections (across ALL connection
  // types: main, ai_languageModel, ai_outputParser, ai_tool, ai_memory, etc.)
  const targetNames = new Set();
  for (const src of sourceNames) {
    const connectionTypes = connections[src] ?? {};
    for (const outputGroups of Object.values(connectionTypes)) {
      for (const group of (outputGroups ?? [])) {
        for (const conn of (group ?? [])) {
          if (conn?.node) targetNames.add(conn.node);
        }
      }
    }
  }

  const triggerTypes = [
    "n8n-nodes-base.webhook",
    "n8n-nodes-base.scheduleTrigger",
    "n8n-nodes-base.manualTrigger",
    "n8n-nodes-base.cronTrigger",
    "n8n-nodes-base.errorTrigger"
  ];

  const deprecatedTypes = [
    "n8n-nodes-base.function",
    "n8n-nodes-base.functionItem"
  ];

  const credentialBearingTypes = new Set(
    nodes.filter(n => n.credentials).map(n => n.type)
  );

  // ---- Findings ----
  const findings = [];

  // 1. Orphan nodes: not a trigger, not a LangChain sub-node provider (model/
  // parser/tool/memory — these have no incoming connection by design), and has
  // no incoming connection from any other node.
  const isLangchainSubNode = (type) =>
    type.startsWith("@n8n/n8n-nodes-langchain.lm") ||
    type.startsWith("@n8n/n8n-nodes-langchain.outputParser") ||
    type.startsWith("@n8n/n8n-nodes-langchain.memory") ||
    type.startsWith("@n8n/n8n-nodes-langchain.tool") ||
    type.startsWith("@n8n/n8n-nodes-langchain.embeddings") ||
    type.startsWith("@n8n/n8n-nodes-langchain.vectorStore") ||
    type.startsWith("@n8n/n8n-nodes-langchain.document");

  const orphanNodes = nodes.filter(n => {
    const isTrigger = triggerTypes.includes(n.type) || /trigger/i.test(n.type);
    if (isTrigger || isLangchainSubNode(n.type)) return false;
    return !targetNames.has(n.name);
  });
  if (orphanNodes.length > 0) {
    findings.push({
      type: "orphan_node",
      severity: "medium",
      nodes: orphanNodes.map(n => n.name),
      detail: "Node(s) are not triggers but have no incoming connection from any other node."
    });
  }

  // 2. Nodes with no outgoing connection (dead ends), excluding known terminal node types
  const terminalTypes = [
    "n8n-nodes-base.respondToWebhook",
    "n8n-nodes-base.noOp"
  ];
  const deadEndNodes = nodes.filter(n => {
    if (terminalTypes.includes(n.type)) return false;
    // LangChain sub-nodes (chat models, output parsers, tools, memory) are
    // legitimately terminal — they feed an agent via a side-channel and have
    // no further "main" output by design.
    if (isLangchainSubNode(n.type)) return false;

    const connectionTypes = connections[n.name] ?? {};
    const hasOutgoing = Object.values(connectionTypes).some(
      outputGroups => (outputGroups ?? []).some(group => (group ?? []).length > 0)
    );
    return !hasOutgoing;
  });
  if (deadEndNodes.length > 0) {
    findings.push({
      type: "dead_end_node",
      severity: "low",
      nodes: deadEndNodes.map(n => n.name),
      detail: "Node(s) have no outgoing connection and are not a recognized terminal node type."
    });
  }

  // 3. No error-handling path anywhere in the workflow
  const hasErrorTrigger = nodes.some(n => n.type === "n8n-nodes-base.errorTrigger");
  const hasOnErrorContinue = nodes.some(n => n.onError === "continueRegularOutput" || n.onError === "continueErrorOutput");
  if (!hasErrorTrigger && !hasOnErrorContinue) {
    findings.push({
      type: "no_error_handling",
      severity: "high",
      nodes: [],
      detail: "Workflow has no Error Trigger node and no node configured with onError continue behavior."
    });
  }

  // 4. Hardcoded / placeholder credential IDs (common copy-paste leftovers)
  const placeholderCredPatterns = /^(REPLACE_ME|TODO|xxxx|placeholder)/i;
  nodes.forEach(n => {
    if (n.credentials) {
      Object.entries(n.credentials).forEach(([credType, cred]) => {
        if (cred?.id && placeholderCredPatterns.test(cred.id)) {
          findings.push({
            type: "placeholder_credential",
            severity: "medium",
            nodes: [n.name],
            detail: `Credential '${credType}' on node '${n.name}' looks like an unfilled placeholder ID.`
          });
        }
      });
    }
  });

  // 5. Deprecated node types
  const deprecatedFound = nodes.filter(n => deprecatedTypes.includes(n.type));
  if (deprecatedFound.length > 0) {
    findings.push({
      type: "deprecated_node",
      severity: "low",
      nodes: deprecatedFound.map(n => n.name),
      detail: "Node(s) use a deprecated node type that may be removed in future n8n versions."
    });
  }

  // 6. Code nodes with no input validation (heuristic: no throw / no try-catch in jsCode)
  const riskyCodeNodes = nodes.filter(n =>
    n.type === "n8n-nodes-base.code" &&
    typeof n.parameters?.jsCode === "string" &&
    !/throw|try\s*{/.test(n.parameters.jsCode)
  );
  if (riskyCodeNodes.length > 0) {
    findings.push({
      type: "unvalidated_code_node",
      severity: "low",
      nodes: riskyCodeNodes.map(n => n.name),
      detail: "Code node(s) have no throw/try-catch, so malformed input may fail silently or produce undefined values downstream."
    });
  }

  // 7. Missing documentation (no sticky notes at all)
  const hasStickyNotes = nodes.some(n => n.type === "n8n-nodes-base.stickyNote");
  if (!hasStickyNotes) {
    findings.push({
      type: "missing_documentation",
      severity: "low",
      nodes: [],
      detail: "Workflow contains no sticky notes documenting purpose, setup, or node-level context."
    });
  }

  // ---- Metrics ----
  const metrics = {
    nodeCount: nodes.length,
    connectionCount: sourceNames.reduce((sum, src) => {
      const connectionTypes = connections[src] ?? {};
      return sum + Object.values(connectionTypes).reduce(
        (typeSum, groups) => typeSum + (groups ?? []).reduce((s, g) => s + (g ?? []).length, 0),
        0
      );
    }, 0),
    triggerCount: nodes.filter(n => triggerTypes.includes(n.type) || /trigger/i.test(n.type)).length,
    credentialBearingNodeTypes: Array.from(credentialBearingTypes),
    aiNodeCount: nodes.filter(n => n.type.startsWith("@n8n/n8n-nodes-langchain")).length,
    orphanNodeCount: orphanNodes.length,
    deadEndNodeCount: deadEndNodes.length,
    deprecatedNodeCount: deprecatedFound.length,
    findingCount: findings.length
  };

  return [{
    json: {
      success: true,
      workflow: wf,
      metrics,
      findings
    }
  }];

} catch (err) {
  return [{
    json: {
      success: false,
      error: err.message
    }
  }];
}

return [{
    json: {
        success: false,
        error: $json.error ?? "Unknown validation error"
    }
}];
